<style>.tpa-table{min-width:720px}.status-assigned{color:#2e9dcc;border-color:#2e9dcc}.status-fix{color:#d95167;border-color:#d95167}.status-ok{color:#30965d;border-color:#30965d}.portal-note{margin-bottom:24px}.tpa-tools{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.tpa-tools button{padding:9px 14px;border:1px solid var(--line);background:#fff;color:var(--text);cursor:pointer}.tpa-tools button.active{background:var(--text);color:#fff}</style>
<div class="notice portal-note">Anda login sebagai TPA bidang <b><?= ucfirst($bidang) ?></b>. Hanya konsultasi yang secara khusus ditugaskan kepada Anda yang ditampilkan.</div><?php if($this->session->flashdata('sukses')):?><div class="notice"><?= htmlspecialchars($this->session->flashdata('sukses')) ?></div><?php endif;?>
<div class="card"><p class="eyebrow">Daftar Penugasan</p><div class="tpa-tools" role="group" aria-label="Filter status"><button class="active" data-filter="semua">Semua</button><button data-filter="ditugaskan">Belum Direview</button><button data-filter="perlu_perbaikan">Perlu Perbaikan</button><button data-filter="direkomendasikan">Sudah Sesuai</button></div><div class="table-wrap"><table class="tpa-table"><thead><tr><th>Nama Pemohon</th><th>Nomor Registrasi</th><th>Putaran</th><th>Status</th><th>Ditugaskan</th><th>Aksi</th></tr></thead><tbody><?php if(empty($daftar)):?><tr><td colspan="6">Belum ada konsultasi yang ditugaskan kepada Anda.</td></tr><?php endif;?><?php foreach($daftar as $r):?><tr data-status="<?= htmlspecialchars($r['status']) ?>"><td><?= htmlspecialchars($r['nama_pemohon']) ?></td><td><b><?= htmlspecialchars($r['nik']?:'—') ?></b><br><small><?= htmlspecialchars($r['no_permohonan']) ?></small></td><td><b><?= (int)$r['putaran'] ?></b><br><small><?= (int)$r['putaran']>1?'Lanjutan perbaikan':'Penugasan awal' ?></small></td><td><span class="badge <?= $r['status']==='direkomendasikan'?'status-ok':($r['status']==='perlu_perbaikan'?'status-fix':'status-assigned') ?>"><?= konsultasi_label_status($r['status']) ?></span></td><td><?= date('d/m/Y H:i',strtotime($r['assigned_at'])) ?></td><td><div class="actions"><?php if($r['status']==='ditugaskan'):?><a class="btn btn-primary" href="<?= base_url('tpa-pengajuan-pbg/review/'.$r['id']) ?>"><?= (int)$r['putaran']>1?'Review Ulang':'Review' ?></a><?php else:?><a class="btn" href="<?= base_url('tpa-pengajuan-pbg/review/'.$r['id']) ?>">Lihat Hasil</a><a class="btn" target="_blank" href="<?= base_url('pengajuan-pbg/berita-acara/'.$r['id']) ?>">Unduh BA</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div>
<script>document.querySelectorAll('.tpa-tools button').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('.tpa-tools button').forEach(function(x){x.classList.remove('active')});b.classList.add('active');document.querySelectorAll('.tpa-table tbody tr[data-status]').forEach(function(r){r.hidden=b.dataset.filter!=='semua'&&r.dataset.status!==b.dataset.filter})})});</script>
